/**
 * Whaleal Cart 安装页 — Free 试用优先，双入口（OAuth + App Store）
 * @author 恒哥
 */
import React, { useState } from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import FreeInstallCta from '../components/FreeInstallCta';
import {
  PRODUCT_NAME,
  PRODUCT_NAME_FULL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
  SHOPIFY_APP_URL,
  buildOAuthInstallUrl,
  normalizeShopDomain,
} from '../constants/brand';
import './page.css';
import '../components/FreeInstallCta/free-install-cta.css';

export default function InstallPage() {
  const [shopInput, setShopInput] = useState('');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const startOAuth = (rawShop) => {
    const shop = normalizeShopDomain(rawShop);
    if (!shop) {
      setError('Enter a valid Shopify store, e.g. my-store or my-store.myshopify.com');
      return false;
    }
    const url = buildOAuthInstallUrl(shop);
    if (!url) {
      setError('Could not build install URL. Check the store domain and try again.');
      return false;
    }
    setSubmitting(true);
    window.location.assign(url);
    return true;
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    startOAuth(shopInput);
  };

  return (
    <Layout>
      <SEO
        title={`Install ${PRODUCT_NAME} free`}
        description={`Install ${PRODUCT_NAME_FULL} on Free — 100 carts, 200 emails, no credit card. Enter your shop domain or use the Shopify App Store.`}
        pathname="/install"
      />
      <div className="page-container about-page">
        <div className="page-header about-header">
          <h1>Install {PRODUCT_NAME} free</h1>
          <p>Start on Free · no credit card · connect in under 2 minutes</p>
        </div>

        <div className="about-content">
          <FreeInstallCta
            variant="inline"
            title="You land on Free first"
            className="install-free-note"
            hideActions
          />

          <section className="about-section" style={{ marginTop: '2rem' }}>
            <h2>Option 1 — Quick install (recommended)</h2>
            <p>
              Enter your Shopify store domain. You will be redirected to Shopify to approve{' '}
              <strong>{PRODUCT_NAME}</strong> and start on the <strong>Free</strong> plan
              (100 carts · 200 emails per month).
            </p>

            <form
              id="install-form"
              onSubmit={handleSubmit}
              className="install-form"
              action="#"
              method="get"
            >
              <label htmlFor="shop-domain" className="install-form-label">
                Shopify store domain
              </label>
              <div className="install-form-row">
                <input
                  id="shop-domain"
                  type="text"
                  name="shop"
                  autoComplete="off"
                  required
                  placeholder="my-store.myshopify.com"
                  value={shopInput}
                  onChange={(e) => {
                    setShopInput(e.target.value);
                    setError('');
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      startOAuth(e.currentTarget.form?.shop?.value || shopInput);
                    }
                  }}
                  className="install-form-input"
                />
                <button
                  type="submit"
                  className="install-form-submit"
                  disabled={submitting}
                >
                  {submitting ? 'Redirecting…' : 'Install free now'}
                </button>
              </div>
              {error && <p className="install-form-error">{error}</p>}
              <p className="install-form-hint">
                Example: <code>dev-whale.myshopify.com</code> or just <code>dev-whale</code>
                <br />
                After click you go to{' '}
                <code>api.whaleal.com/api/auth?shop=…</code> → Shopify OAuth.
              </p>
            </form>
          </section>

          <section className="about-section">
            <h2>Option 2 — Shopify App Store</h2>
            <p>
              Prefer browsing the listing first? Open {PRODUCT_NAME} on the App Store, then install —
              you still start on Free.
            </p>
            <p style={{ marginTop: '1rem' }}>
              <a
                href={SHOPIFY_APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
                className="about-link"
                style={{
                  display: 'inline-block',
                  background: '#0f172a',
                  color: '#fff',
                  padding: '12px 20px',
                  borderRadius: '8px',
                  textDecoration: 'none',
                  fontWeight: 600,
                }}
              >
                Open {SHOPIFY_APP_STORE_LABEL} →
              </a>
            </p>
          </section>

          <section className="about-section">
            <h2>What happens next?</h2>
            <ol>
              <li>Shopify opens the OAuth consent screen for <strong>{PRODUCT_NAME}</strong></li>
              <li>Review permissions (checkouts, customers, discounts, orders)</li>
              <li>After approval, you land in the embedded app at {new URL(SHOPIFY_APP_URL).host} on Free</li>
            </ol>
            <p style={{ marginTop: '16px' }}>
              Compare plans anytime on{' '}
              <Link to="/pricing/" className="about-link">Pricing</Link>
              {' '}· setup help on{' '}
              <Link to="/help/" className="about-link">Help / FAQ</Link>.
            </p>
          </section>
        </div>
      </div>
    </Layout>
  );
}
